package com.langfundamentals;

public class Primitivedatatypes {
	static byte age=22;
	static short no_of_students=10000;
	static int salary=60000;
	static long population=1000000000;
	static float percentage=8.5F;
	static double bank_balance=5000000;
	static char grade='A';
	static boolean javalearner = true;
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Age :" + age);
		System.out.println("Number of Students :" + no_of_students);
		System.out.println("Salary :" + salary);
		System.out.println("Population :" + population);
		System.out.println("percentage :" + percentage);
		System.out.println("Bank_balance :" + bank_balance);
		System.out.println("Grade :" + grade);
		System.out.println("JavaLearner :" + javalearner);
	}

}
